class ITracker:
    def __init__(self, text):
        self.sentences = self._split_into_sentences(text)

    def _is_i_clause(self, clause):
        # A simplistic heuristic: sentence contains " I " or starts with "I "
        stripped = clause.strip()
        return stripped.startswith("I ") or " i " in stripped.lower() or " I," in stripped or " I." in stripped

    def _split_into_sentences(self, text):
        # Split into sentences by period, exclamation, question marks.
        import re
        tokens = re.split(r'(?<=[.!?])\s+', text.strip())
        return [t.strip() for t in tokens if t.strip()]

    def count_i_clauses(self):
        count = 0
        for s in self.sentences:
            # naive: count number of I-clauses in a sentence by counting standalone 'I's
            parts = [p.strip() for p in s.replace(',', ' ').split()]
            count += sum(1 for p in parts if p == 'I')
        return count

def main():
    text = """I think this is a sentence. Another sentence without I. I am counting I-clauses. Is I included? Yes, I am."""
    tracker = ITracker(text)
    print(tracker.count_i_clauses())

if __name__ == "__main__":
    main()

